import {validateBank} from './questions.js';
import {hasCompleteTeaching} from './teaching.js';
import {dayKey,schedule,selectQueue,streak,DAY,validateBackup} from './learning.js';
import {readJSON,saveJSON,loadCustomBank,storeCustomBank,deleteCustomBank} from './storage.js';
import {questionDocument,sourceURL,sourceDocument,readingPage,validSession} from './sources.js';
import {icon} from './icons.js';
import {blankGame,validateGame,gameSummary,eligibleQuestions,startRun,answerRun,nextRun,rateRecall,pauseRun} from './game.js';
import {adventureHub,adventureRun,adventureResults,gameTeaser,formatTime} from './game-ui.js';
import {voiceAvailability,matchSpokenChoice,createVoiceController} from './voice.js';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const VERSION='5.0.0',UPDATE_URL='https://github.com/sola425/ascpi/raw/refs/heads/main/releases/Labwise-latest.apk';
const blank=()=>validateBackup({version:3,records:{},saved:[],log:[],goal:10});
let state=blank(),storageWarning='',recoveryRaw=null,undoState=null;
const initial=readJSON('labwise-state',null);
if(initial.value){try{state=validateBackup({version:3,...initial.value});}catch{storageWarning='Saved progress could not be read safely. Export its recoverable copy before replacing it.';recoveryRaw=initial.value;}}
if(!initial.ok)storageWarning='Device storage is unavailable. Keep a backup of your progress before closing.';
let ui=readJSON('labwise-ui-v4',{bookId:'',readerDoc:'textbook',practice:{topic:'',mode:'all',query:''},cards:{topic:'',mode:'all',query:''}}).value;
ui={playLobby:true,playClock:false,voiceLanguage:'en-US',bookId:'',readerDoc:'textbook',practice:{topic:'',mode:'all',query:''},cards:{topic:'',mode:'all',query:''},...ui};
for(const kind of ['practice','cards'])ui[kind]={topic:'',mode:'all',query:'',...(ui[kind]&&typeof ui[kind]==='object'?ui[kind]:{})};
let catalog={books:[],documents:[]},bank=[],bundledBank=[],byId=new Map(),pages=[],glossary=[],coverage={},view='home',practiceOpen=false,bankCustom=false;
let practice=null,cards=null,searchLimit=40,resultLimit=20,readerOpen=false,bookQuery='',bookTopic='',pageSearchLimit=12,loadReady=false;
let pendingStart=null,pendingImport=null,pendingRestore=null,toastTimer,installPrompt;
let theme=readJSON('labwise-theme',matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light').value;
const topics={Hematology:['#f5e6df','#ad7963','The story inside your blood'],Hemostasis:['#edf0d7','#8e984e','How the body stops a leak'],Immunology:['#ebe5f2','#9c81ae','Meet your body’s defense team'],'Blood bank':['#f7e8e6','#b67d74','The science of a safe match'],Chemistry:['#e9efd9','#859b58','Connect the chemistry of life'],Microbiology:['#e2eee7','#6d957c','A closer look at the tiny world'],Urinalysis:['#f6efd6','#b3a055','Small samples, useful clues'],'Lab essentials':['#e6edf2','#7094a4','Good science begins with good habits'],'Laboratory mathematics':['#e7eadd','#84916b','Make the numbers make sense']};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6000);}
function save(){const r=saveJSON('labwise-state',state);if(!r.ok){storageWarning='Your latest progress is only in memory. Export a backup before closing the app.';notices();}return r.ok;}
function saveUI(){saveJSON('labwise-ui-v4',ui);}
function storeSession(kind){const r=saveJSON(kind==='cards'?'labwise-cards-session':'labwise-session',kind==='cards'?cards:practice);if(!r.ok){storageWarning='Your session cannot be saved on this device. Export progress before closing.';notices();}}
function exportJSON(data,name){const text=JSON.stringify(data,null,2);if(window.LabwiseAndroid){window.LabwiseAndroid.exportJSON(name,text);return;}const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function backup(){exportJSON({version:3,exportedAt:Date.now(),appVersion:VERSION,...state},'labwise-progress.json');}
function bookName(id){return catalog.books.find(b=>b.id===id)?.shortTitle||'All sources';}
function scoped(){return bank.filter(q=>!ui.bookId||q.bookId===ui.bookId);}
function topicNames(book=ui.bookId){return [...new Set(bank.filter(q=>!book||q.bookId===book).map(q=>q.topic))];}
function btn(text,action,primary=false,extra=''){return `<button class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${text}</button>`;}
function title(label,h,p){return `<div class="intro"><p class="eyebrow">${label}</p><h1 tabindex="-1">${h}</h1><p>${p}</p></div>`;}
function empty(h,p,action='setup-practice',label='Choose a session'){return `<div class="empty">${icon('book')}<h2>${h}</h2><p>${p}</p>${action?btn(label,action,true):''}</div>`;}
function scopePills(){return `<div class="book-scope" aria-label="Question source"><button data-book="" class="${!ui.bookId?'active':''}" aria-pressed="${!ui.bookId}">All sources</button>${catalog.books.map(b=>`<button data-book="${b.id}" class="${ui.bookId===b.id?'active':''}" aria-pressed="${ui.bookId===b.id}">${esc(b.shortTitle)}</button>`).join('')}</div>`;}
function sourceLink(q,answer=false){const url=sourceURL(catalog,q,answer),doc=questionDocument(catalog,q,answer),page=answer?(q.answerPage||q.page):q.page;return url?`<a class="source-link" href="${url}" target="_blank" rel="noopener" data-document="${doc.id}" data-page="${page}">${icon('book')}${answer?'Book rationale':'Source question'} · ${esc(doc.shortTitle)} p.${page}</a>`:'';}
function sourceLinks(q){return `<div class="source-links">${sourceLink(q)}${sourceLink(q,true)}</div>`;}
function notices(){let html='';if(storageWarning)html+=`<div class="banner"><p>${esc(storageWarning)}</p>${btn('Export backup','backup')}</div>`;if(recoveryRaw)html+=`<div class="banner"><p>A previous progress copy is available for recovery.</p>${btn('Export recovery copy','recovery')}</div>`;if(undoState)html+=`<div class="banner info"><p>Progress was restored. You can recover the previous progress.</p>${btn('Undo restore','undo-restore')}</div>`;$('#persistent-notice').innerHTML=html;}
function metrics(){const qs=scoped(),ids=new Set(qs.map(q=>q.id)),answered=qs.filter(q=>typeof state.records[q.id]?.correct==='boolean');return {total:qs.length,answered:answered.length,accuracy:answered.length?Math.round(answered.filter(q=>state.records[q.id].correct).length/answered.length*100):null,due:selectQueue(qs,state.records,{mode:'due'}).length,weak:selectQueue(qs,state.records,{mode:'weak'}).length,today:state.log.filter(e=>dayKey(e.at)===dayKey()).length,streak:streak(state.log),saved:state.saved.filter(id=>ids.has(id)).length};}
function resumeBanner(s,kind='practice'){return s&&s.index<s.ids.length?`<div class="resume-banner"><div><strong>Your place is saved.</strong><p>${kind==='cards'?'Flashcards':s.kind==='exam'?'Exam practice':'Practice'} · ${bookName(s.scope?.bookId)} · ${s.index+1} of ${s.ids.length}</p></div>${btn('Continue →',kind==='cards'?'resume-cards':'resume-practice',true)}</div>`:'';}
function home(){const m=metrics(),names=topicNames();return title('A LITTLE CLEARER, EVERY DAY','Make room for a little discovery.','Understand the why, revisit what matters, and build confidence one question at a time.')+scopePills()+resumeBanner(practice)+resumeBanner(cards,'cards')+gameTeaser(gameState())+`<section class="hero"><div><p class="eyebrow">${m.due?'READY FOR ANOTHER LOOK':'YOUR NEXT SMALL STEP'}</p><h2>${m.due?`${m.due} ideas are ready<br>to come back to.`:'Big concepts.<br>Small, satisfying wins.'}</h2><p>${m.due?'A short recall session helps bring an idea back before it fades.':'Your books, explained choices, and memory makers—all together in one calm study space.'}</p>${btn(m.due?'Review due ideas →':`Start ${state.prefs.sessionSize} questions →`,m.due?'setup-due':'setup-practice',true)}</div><div class="hero-art" aria-hidden="true"><div class="orbit"><div class="tube"></div></div></div></section><div class="stats"><div class="stat"><span class="stat-icon">${icon('practice')}</span><div><strong>${m.answered.toLocaleString()}<small> / ${m.total.toLocaleString()}</small></strong><p>Questions explored</p></div></div><div class="stat"><span class="stat-icon">${icon('check')}</span><div><strong>${m.accuracy===null?'—':m.accuracy+'%'}</strong><p>Latest practice accuracy</p></div></div><div class="stat"><span class="stat-icon">${icon('progress')}</span><div><strong>${m.streak}<small> ${m.streak===1?'day':'days'}</small></strong><p>Current study streak</p></div></div></div><div class="daily-strip"><div><strong>Your daily little victory</strong><p>${m.today} / ${state.goal} questions, game answers and recall reviews today</p></div><div class="goal-track"><div class="progress"><span style="width:${Math.min(100,m.today/state.goal*100)}%"></span></div><span>${m.today>=state.goal?'Goal reached. Take that little win.':`${state.goal-m.today} more to your goal`}</span></div><button class="text-btn" data-action="settings">Adjust goal</button></div><div class="section-head"><h2>Choose your next small step</h2><span>Recall. Understand. Revisit.</span></div><div class="paths"><button class="path" data-action="setup-practice">${icon('practice')}<div><strong>Make it make sense</strong><p>A short practice session with explained choices</p></div><span>→</span></button><button class="path" data-action="setup-weak">${icon('refresh')}<div><strong>Give the tricky ones a little time</strong><p>${m.weak} missed answers or forgotten cards</p></div><span>→</span></button><button class="path" data-action="setup-exam">${icon('check')}<div><strong>See what you know</strong><p>Exam practice · feedback when you finish</p></div><span>→</span></button></div><div class="section-head"><h2>A subject to get curious about</h2><span>${bookName(ui.bookId)} · ${names.length} subjects</span></div><div class="topics">${names.map(n=>{const qs=scoped().filter(q=>q.topic===n),done=qs.filter(q=>typeof state.records[q.id]?.correct==='boolean').length,t=topics[n]||['#e8eddf','#809360','Explore this subject'];return `<button class="topic" data-topic="${esc(n)}" style="--tint:${t[0]};--tone:${t[1]}"><div class="topic-top"><span class="topic-symbol">${icon('book')}</span><span>→</span></div><h3>${esc(n)}</h3><p>${esc(t[2])}</p><div class="progress"><span style="width:${done/qs.length*100}%"></span></div><div class="topic-foot"><span>${qs.length} questions</span><span>${done} explored</span></div></button>`}).join('')}</div>`;}
function sourceGapNotice(){return `<details class="notice source-coverage"><summary>About this study collection</summary><p>${catalog.availableQuestions.toLocaleString()} questions are included in practice and flashcards. ${catalog.excludedQuestions||0} questions are excluded from the study collection. The original source PDFs are retained.</p><p>The supplied BOC Part 1 skips printed pages 225–240, leaving ${catalog.missingSourceQuestions||0} question stems unavailable. The missing stems and choices have not been invented.</p></details>`;}
function filters(kind){const f=ui[kind]||ui.practice;return `<div class="toolbar"><input id="${kind}-query" type="search" aria-label="Search questions" placeholder="Search a concept or question number…" value="${esc(f.query)}"><select id="${kind}-topic" aria-label="Filter subject"><option value="">All subjects</option>${topicNames().map(t=>`<option ${t===f.topic?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="${kind}-mode" aria-label="Filter study status">${[['all','All questions'],['new','Not studied yet'],['due','Due for review'],['weak','Needs another look'],['mistakes','Missed practice answers'],['forgotten','Forgotten cards'],['saved','Saved questions']].map(([v,l])=>`<option value="${v}" ${v===f.mode?'selected':''}>${l}</option>`).join('')}</select></div>`;}
function matchQuestions(kind='practice',override={}){const f={bookId:ui.bookId,...ui[kind],...override};let result=selectQueue(bank,state.records,{...f,mode:f.mode==='saved'?'all':f.mode});if(f.mode==='saved')result=result.filter(q=>state.saved.includes(q.id));return result;}
function browse(){const qs=matchQuestions();return title('A QUESTION AT A TIME','Find the next thing that clicks.','Choose your source and subject, then make a session that fits the time you have.')+scopePills()+resumeBanner(practice)+`<div class="session-actions">${btn('Start practice','setup-practice',true)}${btn('Exam practice','setup-exam')}${btn('Saved collection','saved')}</div>`+filters('practice')+`<div class="section-head"><h2>${qs.length.toLocaleString()} matching questions</h2><span>Sessions start small. You choose the size.</span></div>${qs.length?`<div class="question-list">${qs.slice(0,searchLimit).map(q=>`<button class="question-row" data-question="${esc(q.id)}"><span class="row-badges"><span class="badge">${esc(q.topic)}</span><span class="badge book-badge">${esc(bookName(q.bookId))}</span></span><strong>${esc(q.question)}</strong><small>Question ${q.number||'—'} · ${hasCompleteTeaching(q)?'Question and every choice explained':'Original rationale available'}</small>${icon('arrow')}</button>`).join('')}</div>${qs.length>searchLimit?`<div class="section-head">${btn('Show more questions','more-questions')}<span>Showing ${Math.min(searchLimit,qs.length)} of ${qs.length}</span></div>`:''}`:empty('No questions match just yet.','Try another source, clear a filter, or study some questions before using a review-only filter.','reset-filters','Reset filters')}`;}
function words(q){const text=`${q.question} ${q.options.join(' ')} ${q.teaching?.explanation||''}`.toLowerCase();return glossary.filter(g=>{if(g.term==='Mean'&&!/average|deviation|statistic|control|variance|coefficient|data/.test(text))return false;return [g.term,...g.aliases].some(term=>new RegExp(`(?:^|[^a-z])${term.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}(?:$|[^a-z])`,'i').test(text));}).slice(0,6);}
function lesson(q,game=false){const t=q.teaching;if(!t)return `<section class="lesson"><h2>Original book rationale</h2><p class="source">A separate teaching note is not available for this imported item.</p><p>${esc(q.explanation)}</p>${sourceLinks(q)}</section>`;const vocab=words(q);return `<section class="lesson" data-lesson="${esc(q.id)}" aria-label="Explanation"><span class="badge">SIMPLE TEACHING · SOURCE KEPT SEPARATE</span><h2 style="margin-top:13px">Let’s connect the dots.</h2><div class="lesson-tabs" role="tablist" aria-label="Teaching sections">${[['understand','Understand'],['options','Every choice'],['source','Book rationale']].map(([k,l],i)=>`<button role="tab" id="${esc(q.id)}-${k}-tab" aria-controls="${esc(q.id)}-${k}" aria-selected="${!i}" tabindex="${i?-1:0}" data-lesson-tab="${k}">${l}</button>`).join('')}</div><div class="lesson-panel" id="${esc(q.id)}-understand" role="tabpanel" aria-labelledby="${esc(q.id)}-understand-tab" data-lesson-panel="understand"><p>${esc(t.explanation)}</p>${t.sourceNote?`<div class="source-note"><strong>A note about the source</strong><p>${esc(t.sourceNote)}</p></div>`:''}<div class="memory-hook"><strong>Make it stick</strong><p>${esc(t.memory)}</p></div><div class="recall-check"><strong>Try it from memory</strong><p>${esc(t.quickCheck.question)}</p>${game?voicePanel('recall'):''}<details><summary>Check my understanding</summary><p>${esc(t.quickCheck.answer)}</p></details>${game?`<div class="game-recall-ratings"><p>Compare your answer above, then rate your recall.</p>${state.game.active.recalls.some(r=>r.id===q.id)?'<span class="badge">Recall noted for this idea</span>':btn('Review again','game-recall-again',false,recallRevealedFor===voiceContext('recall')?.key?'':'disabled')+btn('I recalled it','game-recall-good',true,recallRevealedFor===voiceContext('recall')?.key?'':'disabled')}</div>`:''}</div>${vocab.length?`<details class="easy-words"><summary>Words made easy</summary><dl>${vocab.map(g=>`<dt>${esc(g.term)}</dt><dd>${esc(g.meaning)}</dd>`).join('')}</dl></details>`:''}</div><div class="lesson-panel" id="${esc(q.id)}-options" role="tabpanel" aria-labelledby="${esc(q.id)}-options-tab" data-lesson-panel="options" hidden><div class="option-lessons">${q.options.map((o,i)=>`<div class="option-lesson ${i===q.answer?'keyed-answer':''}"><div><span class="option-letter">${String.fromCharCode(65+i)}</span><strong>${esc(o)}</strong>${i===q.answer?'<span class="badge">Book’s answer</span>':''}</div><p>${esc(t.optionExplanations[i])}</p></div>`).join('')}</div></div><div class="lesson-panel" id="${esc(q.id)}-source" role="tabpanel" aria-labelledby="${esc(q.id)}-source-tab" data-lesson-panel="source" hidden><p class="source">Original source rationale. Any known source caveats are in Understand.</p><div class="original-rationale">${esc(q.explanation)}</div>${sourceLinks(q)}</div></section>`;}
function context(q){return q.context||q.sharedContext?`<details class="question-context" open><summary>Context for this question</summary><p>${esc(q.context||q.sharedContext)}</p>${q.contextDocumentId&&q.contextPage?`<a class="source-link" href="./${sourceDocument(catalog,q.contextDocumentId)?.path}#page=${q.contextPage}" data-document="${esc(q.contextDocumentId)}" data-page="${q.contextPage}" target="_blank" rel="noopener">Open shared diagram · p.${q.contextPage}</a>`:''}</details>`:'';}
function study(){if(!practice||practice.index>=practice.ids.length)return results();const q=byId.get(practice.ids[practice.index]),picked=practice.selected,show=picked!==null&&practice.kind!=='exam';return title(practice.kind==='exam'?'EXAM PRACTICE · ANSWERS AT THE END':'RECALL FIRST. UNDERSTAND NEXT.',practice.kind==='exam'?'Trust what you’ve learned.':'Let’s make it click.',`${esc(practice.scope?.label||bookName(practice.scope?.bookId))} · ${practice.kind==='exam'?'Your choices are saved as you go.':'Choose first, then explore the idea behind the answer.'}`)+`<div class="study-layout ${show?'with-teaching':''}"><article class="study"><div class="study-top"><span class="badge">${esc(q.topic)}</span><span class="badge book-badge">${esc(bookName(q.bookId))}</span><span>${practice.index+1} / ${practice.ids.length}</span><button class="text-btn" data-action="toggle-save" aria-pressed="${state.saved.includes(q.id)}">${state.saved.includes(q.id)?'♥ Saved':'♡ Save'}</button></div><p class="source">${esc(q.source)}</p><div class="progress"><span style="width:${practice.index/practice.ids.length*100}%"></span></div><h2 class="question-text">${esc(q.question)}</h2>${context(q)}${practice.kind!=='exam'&&q.teaching?`<div class="plain-question"><strong>What this question is asking</strong><p>${esc(q.teaching.questionInPlainEnglish)}</p></div>`:''}${q.needsSource?`<div class="notice">This item uses a figure or table. ${sourceLink(q)}</div>`:''}${picked===null?voicePanel('choice'):''}<div class="options">${q.options.map((o,i)=>`<button class="option ${show?(i===q.answer?'correct':i===picked?'wrong':''):picked===i?'selected':''}" data-answer="${i}" ${picked!==null?'disabled':''}><b>${String.fromCharCode(65+i)}</b><span>${esc(o)}</span>${show&&i===q.answer?'✓':''}</button>`).join('')}</div>${picked!==null?`<div class="answer-status" tabindex="-1" role="status">${practice.kind==='exam'?'Answer recorded. Feedback comes at the end.':picked===q.answer?'✓ Matches the book’s answer.':'The book selects a different answer.'}${show?` Answer: ${String.fromCharCode(65+q.answer)}.`:''}</div>`:''}${sourceLinks(q)}<button class="text-btn" data-action="pause">Pause and keep my place</button></article>${show?lesson(q):''}</div>${picked!==null?`<div class="study-actions"><p>${practice.kind==='exam'?'Your choice is saved.':'Read the idea, explore every choice, or keep going.'}</p>${btn(practice.index===practice.ids.length-1?'See results →':'Next question →','next',true)}</div>`:''}`;}
function results(){if(!practice)return browse();const qs=practice.ids.map(id=>byId.get(id)),right=practice.results.filter(r=>r.correct).length,missed=practice.results.filter(r=>!r.correct);return title('A LITTLE FURTHER THAN BEFORE','Look at what you’ve learned.','Keep the useful ideas. Give the tricky ones another chance later.')+`<section class="panel finish"><span class="badge">SESSION COMPLETE</span><h2 style="margin-top:18px">${right===qs.length?'A satisfying little win.':'Every answer taught you something.'}</h2><div class="score">${right}<small> / ${qs.length}</small></div><p>${Math.round(right/qs.length*100)}% this session · ${esc(practice.scope?.label||bookName(practice.scope?.bookId))}</p><div class="btn-row">${missed.length?btn('Practice missed questions','retry-missed',true):btn('Choose another session','setup-practice',true)}${btn('Back to overview','home')}</div></section><div class="section-head"><h2>Your session, explained</h2><span>Keep the why, not just the letter.</span></div>${qs.slice(0,resultLimit).map((q,i)=>{const r=practice.results[i];return `<details class="panel result-row"><summary><span class="result-dot ${r.correct?'':'wrong'}">${r.correct?'✓':'↻'}</span>${esc(q.question)}</summary><p>Your answer: ${esc(q.options[r.answer])}<br><strong>Book’s answer: ${esc(q.options[q.answer])}</strong></p>${lesson(q)}${sourceLinks(q)}</details>`}).join('')}${qs.length>resultLimit?btn('Show more results','more-results'):''}`;}
function cardsView(){if(!cards||cards.index>=cards.ids.length)return title('THINK. REVEAL. REVISIT.',cards?.index>=cards?.ids.length?'A little more firmly remembered.':'Meet your memory makers.','Try to recall the answer before revealing it. Your recall ratings stay separate from practice accuracy.')+scopePills()+filters('cards')+resumeBanner(cards,'cards')+`<div class="session-actions">${btn('Start a flashcard session','setup-cards',true)}${btn('Review forgotten cards','setup-forgotten')}</div>`+empty(cards?'Card session complete.':'Build a small recall session.',cards?'Your next review dates are saved. Choose another source or come back when your cards are due.':'Pick the source, subject and number of cards that fit your day.','setup-cards','Choose flashcards');const q=byId.get(cards.ids[cards.index]);return title('RECALL FIRST. THEN CONNECT THE DOTS.','Give your memory a moment.',`${esc(cards.scope?.label||bookName(cards.scope?.bookId))} · ${cards.index+1} of ${cards.ids.length} cards`)+`<div class="study-layout ${cards.flipped?'with-teaching':''}"><article class="study flash"><div class="study-top"><span class="badge">${esc(q.topic)}</span><span class="badge book-badge">${esc(bookName(q.bookId))}</span><span>${cards.index+1} / ${cards.ids.length}</span></div><h2 class="question-text">${esc(q.question)}</h2>${context(q)}${cards.flipped?`<div class="flash-answer" tabindex="-1"><span class="badge">THE BOOK’S ANSWER</span><h3>${esc(q.options[q.answer])}</h3><p class="source">Be honest with your recall. Again means you couldn’t remember; Hard still means you got it right.</p></div>`:btn('Reveal answer','flip',true)}${sourceLinks(q)}<div class="btn-row"><button class="text-btn" data-action="skip-card">Skip for now →</button><button class="text-btn" data-action="pause-cards">Pause cards</button></div></article>${cards.flipped?lesson(q):''}</div>${cards.flipped?`<div class="study-actions"><div class="ratings">${[['again','Again','10 min'],['hard','Hard','1 day'],['good','Good',interval(q,'good')],['easy','Easy',interval(q,'easy')]].map(([rating,label,time])=>`<button data-rating="${rating}"><strong>${label}</strong><small>${time}</small></button>`).join('')}</div></div>`:''}`;}
function interval(q,r){const days=Math.round(schedule(state.records[q.id],r,0).due/DAY);return `${days} ${days===1?'day':'days'}`;}
function savedView(){const qs=scoped().filter(q=>state.saved.includes(q.id));return title('YOUR PERSONAL COLLECTION','Keep the tricky ones close.','Save an idea now. Return when you’re ready to make it clearer.')+scopePills()+(qs.length?`<div class="session-actions">${btn('Practice saved questions','setup-saved',true)}</div>${qs.map(q=>`<article class="panel saved-row"><button class="saved-question" data-question="${esc(q.id)}"><span class="badge">${esc(q.topic)}</span> <span class="badge book-badge">${esc(bookName(q.bookId))}</span><strong>${esc(q.question)}</strong><small>Question ${q.number||'—'} · Open practice →</small></button><button class="text-btn" data-remove="${esc(q.id)}">Remove</button></article>`).join('')}`:empty('A little room for later.','Tap Save on any practice question to keep it here.','practice','Explore questions'));}
function progressView(){const m=metrics(),daily={};for(const e of state.log){const k=dayKey(e.at);daily[k]=(daily[k]||0)+1;}const days=Array.from({length:84},(_,i)=>{const k=dayKey(Date.now()-(83-i)*DAY);return {k,n:daily[k]||0};});return title('SEE THE SMALL WINS ADD UP','You’re building understanding.','Practice accuracy measures your latest choices. Recall ratings track what you remembered—each has its own job.')+scopePills()+`<div class="stats"><div class="stat"><span class="stat-icon">${icon('progress')}</span><div><strong>${m.streak}</strong><p>Day study streak</p></div></div><div class="stat"><span class="stat-icon">${icon('refresh')}</span><div><strong>${m.due}</strong><p>Ideas due for review</p></div></div><div class="stat"><span class="stat-icon">${icon('check')}</span><div><strong>${m.accuracy===null?'—':m.accuracy+'%'}</strong><p>Latest practice accuracy</p></div></div></div><section class="panel"><div class="section-head" style="margin-top:0"><h2>A little consistency</h2><span>Past12weeks · Lagos time</span></div><div class="heatmap">${days.map(d=>`<span class="heat-cell level-${Math.min(4,Math.ceil(d.n/3))}" title="${d.k}: ${d.n} study interactions" aria-label="${d.k}: ${d.n} study interactions"></span>`).join('')}</div><p class="source">Each square is a day. Practice and self-rated recall both count toward your daily effort.</p></section><div class="section-head"><h2>Where to focus next</h2><span>Based on your latest practice answers</span></div><div class="subject-progress">${topicNames().map(topic=>{const qs=scoped().filter(q=>q.topic===topic),done=qs.filter(q=>typeof state.records[q.id]?.correct==='boolean'),right=done.filter(q=>state.records[q.id].correct).length,rate=done.length?Math.round(right/done.length*100):0;return `<button class="panel" data-topic="${esc(topic)}"><strong>${esc(topic)}</strong><span>${done.length?rate+'%':'Not started'}</span><div class="progress"><span style="width:${rate}%"></span></div><small>${done.length} of ${qs.length} explored</small></button>`;}).join('')}</div><section class="panel backup-panel"><h2>Keep your hard work.</h2><p>Your progress stays on this device. Export a backup before clearing app data, changing phones, or uninstalling. A progress backup contains your history, game XP, quests, current adventure and reading positions; export a custom bank separately.</p><div class="btn-row">${btn('Export progress','backup',true)}${btn('Restore progress','restore')}${btn('Study settings','settings')}</div></section>`;}
function bookResults(){if(!bookQuery&&!bookTopic)return '';const results=pages.filter(p=>(!ui.bookId||p.bookId===ui.bookId)&&(!bookTopic||p.topic===bookTopic)&&(!bookQuery||p.text.toLowerCase().includes(bookQuery.toLowerCase())));return `<div class="section-head"><h2>${results.length} matching pages</h2><span>Each result keeps its own PDF identity.</span></div><div class="book-results">${results.slice(0,pageSearchLimit).map(p=>{const doc=sourceDocument(catalog,p.documentId),pos=bookQuery?p.text.toLowerCase().indexOf(bookQuery.toLowerCase()):0,text=p.text.slice(Math.max(0,pos-65),Math.max(0,pos-65)+220).replace(/\s+/g,' ');return `<button class="book-result" data-document="${doc.id}" data-page="${p.page}" data-read-here="true"><span class="badge book-badge">${esc(doc.shortTitle)} · p.${p.page}</span><strong>${esc(p.topic||'Source text')}</strong><p>${esc(text)}…</p><span>Read this page →</span></button>`;}).join('')}</div>${results.length>pageSearchLimit?btn('Show more pages','more-pages'):''}`;}
function library(){const doc=sourceDocument(catalog,ui.readerDoc)||catalog.documents[0],page=readingPage(catalog,doc.id,state.reading[doc.id]||1);return title('YOUR BOOKS. YOUR PACE.','A whole shelf of understanding.','Read the source, explore a concept, and keep your place across both collections.')+scopePills()+`<div class="library-grid">${catalog.books.filter(b=>!ui.bookId||b.id===ui.bookId).map(b=>`<section class="panel library-card"><div class="book-cover ${b.id==='boc7'?'boc':''}" aria-hidden="true">${b.id==='boc7'?'BOC<br>STUDY<br>GUIDE':'SUCCESS<br>IN CLINICAL<br>LAB SCIENCE'}<small>${esc(b.edition.split(' · ')[0])}</small></div><div><span class="badge book-badge">${b.questions.toLocaleString()} STUDY QUESTIONS</span><h2>${esc(b.title)}</h2><p>${esc(b.description)}</p><div class="btn-row">${b.documents.map(id=>{const d=sourceDocument(catalog,id);return `<button class="btn" data-document="${id}" data-page="${state.reading[id]||1}" data-read-here="true">${b.documents.length>1?'Part '+d.part:'Read book'} →</button>`;}).join('')}</div><p class="coverage-label">${bank.filter(q=>q.bookId===b.id&&hasCompleteTeaching(q)).length.toLocaleString()} separate teaching notes${b.missingQuestions?` · ${b.missingQuestions} source questions missing from supplied pages`:''}</p></div></section>`).join('')}</div>${sourceGapNotice()}<section class="panel book-search"><h2>Find it in your sources</h2><div class="toolbar"><input id="book-search" type="search" aria-label="Search source pages" placeholder="Try PCR, hemoglobin, or a phrase…" value="${esc(bookQuery)}"><select id="book-topic" aria-label="Filter source pages by subject"><option value="">All subjects</option>${[...new Set(pages.filter(p=>!ui.bookId||p.bookId===ui.bookId).map(p=>p.topic))].filter(Boolean).map(t=>`<option ${t===bookTopic?'selected':''}>${esc(t)}</option>`).join('')}</select>${btn('Search pages','search-book',true)}</div><div id="book-results">${bookResults()}</div></section><section class="panel reader" id="reader"><div class="section-head"><h2>Your place in the book</h2><form id="page-form"><select class="field" id="reader-document" aria-label="Choose PDF">${catalog.documents.map(d=>`<option value="${d.id}" ${d.id===doc.id?'selected':''}>${esc(d.shortTitle)} · ${d.pages} pages</option>`).join('')}</select><label for="page-number">Page</label><input id="page-number" type="number" min="1" max="${doc.pages}" value="${page}" required><button class="btn" type="submit">Go →</button></form></div><p class="source">${esc(doc.title)} · Local PDF pages 1–${doc.pages}. Printed book page numbers may differ. Your selected page is saved on this device.</p><div class="btn-row" style="margin-bottom:17px"><a class="btn primary" href="./${doc.path}#page=${page}" data-document="${doc.id}" data-page="${page}" target="_blank" rel="noopener">Open reader ↗</a>${window.LabwiseAndroid?'<span class="badge">All PDFs bundled offline</span>':btn('Keep this PDF offline','cache-pdf')}</div>${readerOpen&&!window.LabwiseAndroid?`<object class="pdf-view" type="application/pdf" data="./${doc.path}#page=${page}"><p>Your browser cannot embed this PDF. Use Open reader above.</p></object>`:empty('Read whenever you’re ready.','The Android app includes a native reader with zoom and page jumps. In a browser, open a separate tab or read here.','open-reader','Read here')}${!window.LabwiseAndroid?'<p class="source">The app data works offline after caching. Cache each PDF separately to read its original pages offline in a browser.</p>':''}</section><section class="panel backup-panel"><h2>Your own explained collection</h2><p>Import an explained JSON question bank to use instead of the bundled collection. We’ll preview it first. Progress for existing IDs stays intact.</p><div class="btn-row">${btn('Import bank','import')}${btn('Export current bank','export-bank')}${bankCustom?btn('Use bundled books','bundled'):''}</div></section>`;}
function setIcons(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
function render({focus=false}={}){if(!loadReady)return;document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);active?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current');});$('#content').innerHTML=view==='home'?home():view==='play'?playView():view==='practice'?(practiceOpen&&practice?study():browse()):view==='cards'?cardsView():view==='library'?library():view==='saved'?savedView():progressView();notices();if(focus)$('h1')?.focus({preventScroll:true});}
function navigate(next,{session=false,replace=false}={}){flushGameClock();clearVoice();if(!['home','play','practice','cards','library','saved','progress'].includes(next))next='home';view=next;practiceOpen=session;history[replace?'replaceState':'pushState']({view,session},'',`#${view}`);render({focus:true});window.scrollTo(0,0);}
function modal(titleText,body,footer=''){const d=$('#modal');d.innerHTML=`<div class="dialog-heading"><h2>${titleText}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div>${body}<div class="dialog-footer">${footer}</div>`;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close();}
function openSetup(kind='practice',overrides={}){const f=view==='cards'?ui.cards:ui.practice,scope={bookId:ui.bookId,topic:['home','progress'].includes(view)?'':f.topic,query:['home','progress'].includes(view)?'':f.query,mode:'all',...f,...(['home','progress'].includes(view)?{topic:'',query:'',mode:'all'}:{}),...overrides};pendingStart={kind,scope};modal(kind==='cards'?'A little recall session.':kind==='exam'?'Make an exam session.':'Make a little progress.',`<p>Choose a source, subject and a comfortable number of ${kind==='cards'?'cards':'questions'}. Your unfinished session stays safe until you choose to replace it.</p><div class="form-grid"><label class="wide">Source<select class="field" id="setup-book"><option value="">All sources</option>${catalog.books.map(b=>`<option value="${b.id}" ${b.id===scope.bookId?'selected':''}>${esc(b.shortTitle)}</option>`).join('')}</select></label><label class="wide">Subject<select class="field" id="setup-topic"><option value="">All subjects</option>${topicNames(scope.bookId).map(t=>`<option ${t===scope.topic?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Study status<select class="field" id="setup-mode">${[['all','All questions'],['new','Not studied yet'],['due','Due for review'],['weak','Needs another look'],['forgotten','Forgotten cards'],['saved','Saved questions']].map(([k,l])=>`<option value="${k}" ${k===scope.mode?'selected':''}>${l}</option>`).join('')}</select></label><label>Session size<select class="field" id="setup-size">${[5,10,20,50,100].map(n=>`<option value="${n}" ${n===(kind==='exam'?20:state.prefs.sessionSize)?'selected':''}>${n}</option>`).join('')}</select></label></div><label class="checkbox-label"><input type="checkbox" id="setup-shuffle" checked>Mix the question order</label><p class="source" id="setup-count"></p>`,btn('Cancel','close-dialog')+btn('Start session →','confirm-session',true));setupCount();}
function setupScope(){return {...pendingStart.scope,bookId:$('#setup-book').value,topic:$('#setup-topic').value,mode:$('#setup-mode').value};}
function setupCount(){if(!pendingStart||!$('#setup-count'))return;const f=setupScope(),n=matchQuestions('practice',f).length;$('#setup-count').textContent=`${n.toLocaleString()} matching questions · ${Math.min(n,Number($('#setup-size').value))} in this session. Short sessions can be repeated.`;}
function prepareSession(){const scope=setupScope(),kind=pendingStart.kind;let qs=matchQuestions('practice',scope);if(!qs.length){toast('No questions match this setup. Change the source, subject or status.');return;}qs=selectQueue(qs,state.records,{limit:Number($('#setup-size').value),randomize:$('#setup-shuffle').checked});pendingStart={kind,scope:{...scope,label:`${bookName(scope.bookId)}${scope.topic?' · '+scope.topic:''}`},ids:qs.map(q=>q.id)};const old=kind==='cards'?cards:practice;if(old&&old.index<old.ids.length){modal('Keep your place?',`<p>You have an unfinished ${kind==='cards'?'flashcard':old.kind==='exam'?'exam':'practice'} session: ${old.index+1} of ${old.ids.length}. Resume it, or replace it with this new ${pendingStart.ids.length}-item session.</p>`,btn('Resume existing','resume-existing')+btn('Start new session','start-new',true));return;}startPrepared();}
function startPrepared(){const s={version:2,kind:pendingStart.kind,scope:pendingStart.scope,ids:pendingStart.ids,index:0,selected:null,results:[],flipped:false,createdAt:Date.now(),committed:false};if(s.kind==='cards')cards=s;else practice=s;storeSession(s.kind);closeModal();navigate(s.kind==='cards'?'cards':'practice',{session:s.kind!=='cards'});pendingStart=null;}
function record(q,correct,rating,kind='answer'){const now=Date.now();state.records[q.id]=schedule(state.records[q.id],rating,now);if(kind==='answer')Object.assign(state.records[q.id],{correct,at:now});else Object.assign(state.records[q.id],{lastRecallRating:rating,lastRecallAt:now});state.log.push({id:q.id,correct,at:now,kind});save();}
function answer(i){clearVoice();if(!practice||practice.selected!==null||practice.index>=practice.ids.length)return;const q=byId.get(practice.ids[practice.index]);if(i<0||i>=q.options.length)return;const correct=i===q.answer;practice.selected=i;practice.results.push({id:q.id,answer:i,correct});if(practice.kind!=='exam')record(q,correct,correct?'good':'again');storeSession('practice');render();$('.answer-status')?.focus();}
function nextQuestion(){clearVoice();if(!practice||practice.selected===null)return;practice.index++;practice.selected=null;if(practice.index===practice.ids.length&&practice.kind==='exam'&&!practice.committed){for(const r of practice.results)record(byId.get(r.id),r.correct,r.correct?'good':'again');practice.committed=true;}storeSession('practice');resultLimit=20;render({focus:true});window.scrollTo(0,0);}
function rateCard(rating){if(!cards||!cards.flipped||cards.index>=cards.ids.length)return;const q=byId.get(cards.ids[cards.index]);record(q,rating!=='again',rating,'review');cards.results.push({id:q.id,rating});cards.index++;cards.flipped=false;storeSession('cards');render({focus:true});window.scrollTo(0,0);}
function openDocument(id,n,here=false){const doc=sourceDocument(catalog,id);if(!doc){toast('This source document is not available.');return;}const page=readingPage(catalog,id,n);ui.readerDoc=id;state.reading[id]=page;save();saveUI();if(window.LabwiseAndroid){if(window.LabwiseAndroid.openDocument)window.LabwiseAndroid.openDocument(id,page);else if(id==='textbook')window.LabwiseAndroid.openTextbook(page);else toast('Install the latest APK to open the new BOC sources.');return;}if(here){readerOpen=true;view='library';render();$('#reader')?.scrollIntoView({behavior:'smooth'});}else window.open(`./${doc.path}#page=${page}`,'_blank','noopener');}
function settings(){modal('Your study space.',`<p>Make learning comfortable. Changes stay on this device.</p><div class="settings-row"><div><strong>Appearance</strong><p>Light or dark, whichever feels clearer.</p></div>${btn(theme==='dark'?'Use light':'Use dark','theme')}</div><div class="settings-row"><label for="font-size">Reading size</label><select class="field" id="font-size">${[[1,'Standard'],[1.15,'Larger'],[1.3,'Largest']].map(([n,l])=>`<option value="${n}" ${state.prefs.fontScale===n?'selected':''}>${l}</option>`).join('')}</select></div><div class="settings-row"><label for="goal">Daily effort goal</label><select class="field" id="goal">${[5,10,20,30].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} / day</option>`).join('')}</select></div><div class="settings-row"><label for="default-size">Default session</label><select class="field" id="default-size">${[5,10,20,50].map(n=>`<option value="${n}" ${state.prefs.sessionSize===n?'selected':''}>${n} questions</option>`).join('')}</select></div><div class="settings-row"><label for="voice-language">Voice recognition language</label><select class="field" id="voice-language">${[['en-US','English (US)'],['en-GB','English (UK)'],['en-IN','English (India)'],['en-NG','English (Nigeria)']].map(([v,l])=>`<option value="${v}" ${ui.voiceLanguage===v?'selected':''}>${l}</option>`).join('')}</select></div><p class="source">Voice is handled by your device or browser and may require a connection. Labwise saves no audio. Check the transcription before confirming.</p><div class="settings-row"><div><strong>Labwise ${VERSION}</strong><p>Same app identity. New APK downloads use the latest link.</p></div>${btn('Get latest APK','updates')}</div><p class="source" style="margin-top:18px">Review intervals are a simple deterministic schedule, not FSRS. Progress stays on this device. Export a backup before uninstalling or moving to a new phone.</p>`,btn('Export progress','backup')+btn('Done','close-dialog',true));}
async function cachePDF(button){const d=sourceDocument(catalog,ui.readerDoc);button.disabled=true;button.textContent='Saving source…';try{if(!('caches'in window))throw Error();const r=await fetch('./'+d.path);if(!r.ok)throw Error();await(await caches.open('labwise-books-v2')).put('./'+d.path,r);button.textContent='✓ Available offline';toast(d.shortTitle+' is saved for offline reading. Browser storage can still be evicted.');}catch{button.disabled=false;button.textContent='Try offline download again';toast('Could not cache this PDF. Check available storage and connection.');}}
function applyTheme(){document.documentElement.dataset.theme=theme;document.documentElement.style.setProperty('--font-scale',state.prefs.fontScale);saveJSON('labwise-theme',theme);}
function lessonTab(button){clearVoice();const group=button.closest('.lesson'),key=button.dataset.lessonTab;group.querySelectorAll('[data-lesson-tab]').forEach(b=>{const selected=b===button;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});group.querySelectorAll('[data-lesson-panel]').forEach(p=>p.hidden=p.dataset.lessonPanel!==key);}

function gameState(){return state.game||blankGame();}
function playView(){const g=gameState(),a=g.active;if(!a||ui.playLobby)return adventureHub({game:g,bank:scoped(),sourcePills:scopePills(),scopeName:bookName(ui.bookId),timed:!!ui.playClock});if(a.phase==='complete')return adventureResults(g);const q=byId.get(a.queue[a.index].id);if(!q)return adventureHub({game:g,bank:scoped(),sourcePills:scopePills()});return adventureRun({game:g,q,lessonHTML:lesson(q,true),voiceHTML:voicePanel('choice'),timed:!!ui.playClock});}
let recallRevealedFor='',pendingGameTopic='',gameClockPending=0,gameClockLast=performance.now();
function startAdventure(topic='',replace=false){if(eligibleQuestions(scoped(),{topic}).length<5){toast('This room needs five short questions. Longer cases are available in Practice.');return;}const g=gameState();pendingGameTopic=topic;if(g.active&&g.active.phase!=='complete'&&!replace){modal('Keep your adventure?',`<p>Your unfinished ${esc(g.active.topic||'mixed-subject')} round is saved. Continue it, or start a new five-question round.</p>`,btn('Continue saved round','game-resume')+btn('Start new round','game-replace',true));return;}try{state.game=startRun({...g,active:null},scoped(),{topic,now:Date.now(),seed:Math.floor(Math.random()*0xffffffff)});ui.playLobby=false;gameClockPending=0;save();saveUI();closeModal();navigate('play');}catch(error){toast(error.message);}}
function flushGameClock(){if(gameClockPending>0&&state.game?.active?.phase==='question'){state.game=pauseRun(state.game,bank,{elapsedMs:Math.round(gameClockPending)});gameClockPending=0;save();}gameClockLast=performance.now();}
function gameAnswer(index){const a=state.game?.active;if(!a||a.phase!=='question')return;const q=byId.get(a.queue[a.index].id);if(!q)return;clearVoice();try{const next=answerRun(state.game,bank,index,{now:Date.now(),elapsedMs:Math.round(gameClockPending)});if(next.active?.answers.length===a.answers.length)return;state.game=next;gameClockPending=0;const correct=index===q.answer,now=Date.now();state.records[q.id]={...schedule(state.records[q.id],correct?'good':'again',now),lastGameCorrect:correct,lastGameAt:now};state.log.push({id:q.id,correct,at:now,kind:'game'});save();render();window.scrollTo(0,0);$('.game-feedback-banner')?.focus({preventScroll:true});}catch(error){toast(error.message);}}
function gameNext(){if(state.game?.active?.phase!=='feedback')return;clearVoice();state.game=nextRun(state.game,bank,{now:Date.now()});gameClockPending=0;gameClockLast=performance.now();save();render({focus:true});window.scrollTo(0,0);}
function gameRecall(rating){if(recallRevealedFor!==voiceContext('recall')?.key)return;const a=state.game?.active;if(!a||a.phase!=='feedback')return;const q=byId.get(a.queue[a.index].id);if(!q||a.recalls.some(r=>r.id===q.id))return;state.game=rateRecall(state.game,bank,rating,{now:Date.now()});record(q,rating!=='again',rating,'review');clearVoice();render();toast(rating==='again'?'Recall noted. This idea is due again in ten minutes.':'Recall noted. Your next review is scheduled.');}
setInterval(()=>{const now=performance.now(),delta=now-gameClockLast;gameClockLast=now;if(view==='play'&&!ui.playLobby&&state.game?.active?.phase==='question'&&ui.playClock&&document.visibilityState==='visible'&&!$('#modal').open&&!['listening','processing'].includes(voiceDraft.status)){gameClockPending+=Math.min(delta,2000);const clock=$('.game-clock');if(clock)clock.textContent=formatTime(state.game.active.elapsedMs+gameClockPending);}},1000);
document.addEventListener('visibilitychange',()=>{gameClockLast=performance.now();});

let voiceDraft={context:null,status:'idle',text:'',error:'',mode:'choice',open:false};
const speech=createVoiceController({onState:({status,context})=>{if(context===voiceDraft.context){voiceDraft.status=status;refreshVoice();}},onResult:({text,context})=>{if(context!==voiceContext(voiceDraft.mode)?.key)return;voiceDraft={...voiceDraft,status:'idle',text,open:true,error:''};refreshVoice();$('#spoken-answer')?.focus();},onError:({message,context})=>{if(context!==voiceDraft.context)return;voiceDraft={...voiceDraft,status:'idle',error:message,open:true};refreshVoice();}});
function voiceContext(mode='choice'){if(view==='practice'&&practiceOpen&&practice&&practice.selected===null&&practice.index<practice.ids.length&&mode==='choice'){const q=byId.get(practice.ids[practice.index]);return q?{key:`practice:${practice.createdAt||practice.started}:${practice.index}:${q.id}`,q,mode}:null;}const a=state.game?.active;if(view==='play'&&!ui.playLobby&&a&&((a.phase==='question'&&mode==='choice')||(a.phase==='feedback'&&mode==='recall'))){const q=byId.get(a.queue[a.index].id);return q?{key:`game:${a.id}:${a.index}:${mode}:${q.id}`,q,mode}:null;}return null;}
function voicePanel(mode='choice'){const c=voiceContext(mode);if(!c)return '';const d=voiceDraft.context===c.key?voiceDraft:{context:c.key,status:'idle',text:'',error:'',open:false},busy=['listening','processing'].includes(d.status),available=voiceAvailability().available;return `<section class="voice-answer" data-voice-mode="${mode}"><div class="voice-heading"><span class="voice-mic ${busy?'listening':''}">${icon('mic')}</span><div><strong>${mode==='recall'?'Try saying your recall answer':'You can answer with your voice'}</strong><p>${mode==='recall'?'Speak, then compare with the suggested answer.':'Say “option B”, or speak an answer. You confirm the choice.'}</p></div></div><div class="btn-row">${busy?btn('Cancel microphone','voice-cancel'):btn('Speak answer','voice-start',false,available?'':'disabled')}${btn('Type instead','voice-type')}</div>${!available?'<p class="voice-help">Speech is unavailable in this browser. You can type here or tap a choice.</p>':''}${busy?`<p class="voice-status" role="status">${d.status==='listening'?'Listening…':'Finishing transcription…'}</p>`:''}${d.error?`<p class="voice-error" role="status">${esc(d.error)}</p>`:''}${d.open||d.text?`<label class="voice-transcript-label" for="spoken-answer">${mode==='recall'?'Your recall answer':'Check or edit what was heard'}</label><textarea id="spoken-answer" rows="2" maxlength="12000" autocomplete="off" spellcheck="false">${esc(d.text)}</textarea><div class="voice-match" role="status">${voiceMatchText(c,d.text)}</div>${btn(mode==='recall'?'Reveal suggested answer':'Confirm spoken answer','voice-confirm',true,voiceCanConfirm(c,d.text)?'':'disabled')}`:''}</section>`;}
function voiceMatchText(c,text){if(!text.trim())return 'Your words will appear here.';if(c.mode==='recall')return 'Compare your answer, then rate your own recall.';const match=matchSpokenChoice(text,c.q.options);return match.index===null?'No single choice matched. Edit the text, say an option letter, or tap a choice.':`Suggested choice ${String.fromCharCode(65+match.index)}: ${esc(c.q.options[match.index])}`;}
function voiceCanConfirm(c,text){return text.trim()&&(c.mode==='recall'||matchSpokenChoice(text,c.q.options).index!==null);}
function refreshVoice(){const box=$('.voice-answer');if(box)box.outerHTML=voicePanel(box.dataset.voiceMode);}
function clearVoice(){speech.cancel();voiceDraft={context:null,status:'idle',text:'',error:'',mode:'choice',open:false};}
function requestVoice(mode='choice'){const c=voiceContext(mode);if(!c)return;if(!ui.voiceAcknowledged){ui.pendingVoiceMode=mode;modal('Answer by speaking.',`<p>Your device or browser handles speech recognition and may use an online service. Offline speech depends on your device and installed languages.</p><p>Labwise does not save your audio. You’ll see an editable transcription and confirm a choice before it is scored.</p>`,btn('Cancel','close-dialog')+btn('Use voice input','voice-consent',true));return;}startVoiceNow(mode);}
function startVoiceNow(mode='choice'){const c=voiceContext(mode);if(!c)return;clearVoice();voiceDraft={context:c.key,mode,status:'idle',text:'',error:'',open:true};refreshVoice();speech.start(c.key,ui.voiceLanguage||'en-US');}
function confirmVoice(){const c=voiceContext(voiceDraft.mode);if(!c||c.key!==voiceDraft.context)return;const text=$('#spoken-answer')?.value||voiceDraft.text;if(c.mode==='recall'){const d=$('.game-teaching .recall-check details');if(d){d.open=true;d.scrollIntoView({block:'nearest'});}return;}const m=matchSpokenChoice(text,c.q.options);if(m.index===null){toast('Choose one option letter or edit the answer.');return;}if(view==='play')gameAnswer(m.index);else answer(m.index);}
document.addEventListener('input',event=>{if(event.target.id!=='spoken-answer')return;voiceDraft.text=event.target.value;const c=voiceContext(voiceDraft.mode);if(!c)return;const match=$('.voice-match');if(match)match.innerHTML=voiceMatchText(c,voiceDraft.text);const confirm=$('[data-action="voice-confirm"]');if(confirm)confirm.disabled=!voiceCanConfirm(c,voiceDraft.text);});
document.addEventListener('focusin',event=>{if(view!=='play'||!event.target.closest('.game-teaching'))return;const bar=$('.game-next');if(!bar||getComputedStyle(bar).position!=='fixed')return;requestAnimationFrame(()=>{if(!event.target.isConnected)return;const r=event.target.getBoundingClientRect(),header=$('.app-header').getBoundingClientRect(),bottom=bar.getBoundingClientRect().top-10,top=Math.max(0,header.bottom)+10;if(r.bottom>bottom)window.scrollBy(0,r.bottom-bottom);else if(r.top<top)window.scrollBy(0,r.top-top);});});
window.addEventListener('pagehide',()=>{speech.cancel();});
document.addEventListener('toggle',event=>{if(event.target.matches('.game-teaching .recall-check details')&&event.target.open){recallRevealedFor=voiceContext('recall')?.key||'';document.querySelectorAll('.game-recall-ratings button').forEach(b=>b.disabled=false);}},true);

document.addEventListener('click',async e=>{
 const docLink=e.target.closest('[data-document]');if(docLink){e.preventDefault();openDocument(docLink.dataset.document,Number(docLink.dataset.page),docLink.dataset.readHere==='true');return;}
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.view){navigate(b.dataset.view);return;}if(b.dataset.book!==undefined){ui.bookId=b.dataset.book;for(const k of ['practice','cards'])if(!topicNames().includes(ui[k].topic))ui[k].topic='';saveUI();render();return;}
 if(b.dataset.gameTopic!==undefined){startAdventure(b.dataset.gameTopic);return;}if(b.dataset.gameAnswer!==undefined){gameAnswer(Number(b.dataset.gameAnswer));return;}
 if(b.dataset.topic){ui.practice.topic=b.dataset.topic;ui.practice.mode='all';ui.practice.query='';saveUI();navigate('practice');return;}
 if(b.dataset.question){const q=byId.get(b.dataset.question);pendingStart={kind:'practice',ids:[q.id],scope:{bookId:q.bookId,label:bookName(q.bookId)}};if(practice&&practice.index<practice.ids.length){modal('Keep your place?',`<p>Your unfinished ${practice.ids.length}-question session is saved. Resume it, or replace it with this one-question session.</p>`,btn('Resume existing','resume-existing')+btn('Open this question','start-new',true));}else startPrepared();return;}
 if(b.dataset.answer!==undefined){answer(Number(b.dataset.answer));return;}if(b.dataset.rating){rateCard(b.dataset.rating);return;}if(b.dataset.lessonTab){lessonTab(b);return;}if(b.dataset.remove){state.saved=state.saved.filter(id=>id!==b.dataset.remove);save();render();return;}
 switch(b.dataset.action){
 case 'game-hub':flushGameClock();clearVoice();ui.playLobby=true;saveUI();navigate('play');break;
 case 'game-start':startAdventure(ui.playLobby?'':state.game?.active?.topic||'');break;
 case 'game-replace':startAdventure(pendingGameTopic,true);break;
 case 'game-resume':closeModal();ui.playLobby=false;saveUI();navigate('play');break;
 case 'game-pause':flushGameClock();clearVoice();ui.playLobby=true;saveUI();navigate('play');break;
 case 'game-next':gameNext();break;case 'game-recall-again':gameRecall('again');break;case 'game-recall-good':gameRecall('good');break;
 case 'game-cards':navigate('cards');break;
 case 'voice-start':requestVoice(b.closest('.voice-answer')?.dataset.voiceMode||'choice');break;
 case 'voice-consent':{ui.voiceAcknowledged=true;const mode=ui.pendingVoiceMode||'choice';delete ui.pendingVoiceMode;saveUI();closeModal();startVoiceNow(mode);break;}
 case 'voice-cancel':clearVoice();refreshVoice();break;
 case 'voice-type':{const mode=b.closest('.voice-answer')?.dataset.voiceMode||'choice',c=voiceContext(mode);if(c){speech.cancel();voiceDraft={...voiceDraft,context:c.key,mode,open:true,status:'idle',error:''};refreshVoice();$('#spoken-answer')?.focus();}break;}
 case 'voice-confirm':confirmVoice();break;

 case 'home':navigate('home');break;case 'practice':navigate('practice');break;case 'library':navigate('library');break;case 'saved':navigate('saved');break;
 case 'setup-practice':openSetup('practice');break;case 'setup-exam':openSetup('exam');break;case 'setup-cards':openSetup('cards');break;case 'setup-due':openSetup('cards',{mode:'due'});break;case 'setup-weak':openSetup('practice',{mode:'weak'});break;case 'setup-forgotten':openSetup('cards',{mode:'forgotten'});break;case 'setup-saved':openSetup('practice',{mode:'saved'});break;
 case 'confirm-session':prepareSession();break;case 'start-new':startPrepared();break;case 'resume-existing':{const kind=pendingStart.kind;closeModal();navigate(kind==='cards'?'cards':'practice',{session:kind!=='cards'});break;}
 case 'resume-practice':navigate('practice',{session:true});break;case 'resume-cards':navigate('cards');break;case 'pause':navigate('home');break;case 'pause-cards':navigate('home');break;case 'next':nextQuestion();break;
 case 'retry-missed':{const ids=practice.results.filter(r=>!r.correct).map(r=>r.id);if(ids.length){pendingStart={kind:'practice',ids,scope:practice.scope};startPrepared();}break;}
 case 'toggle-save':{const id=practice.ids[practice.index];state.saved=state.saved.includes(id)?state.saved.filter(v=>v!==id):[...state.saved,id];save();render();break;}
 case 'flip':cards.flipped=true;storeSession('cards');render();$('.flash-answer')?.focus();break;
 case 'skip-card':cards.index++;cards.flipped=false;storeSession('cards');render({focus:true});break;
 case 'more-questions':searchLimit+=40;render();break;case 'more-results':resultLimit+=20;render();break;case 'reset-filters':ui.practice={topic:'',mode:'all',query:''};saveUI();render();break;
 case 'settings':settings();break;case 'theme':theme=theme==='dark'?'light':'dark';applyTheme();settings();break;case 'close-dialog':closeModal();break;
 case 'backup':backup();break;case 'restore':$('#progress-input').click();break;case 'recovery':exportJSON({recoveredAt:Date.now(),raw:recoveryRaw},'labwise-recovery-copy.json');break;
 case 'confirm-restore':{clearVoice();flushGameClock();const previous=state;saveJSON('labwise-state-previous',previous);undoState=previous;state=pendingRestore;state.game=validateGame(state.game,bank);pendingRestore=null;save();applyTheme();closeModal();render();toast('Progress restored. Undo is available above.');break;}
 case 'undo-restore':clearVoice();state=undoState;undoState=null;save();render();toast('Previous progress restored.');break;
 case 'import':$('#bank-input').click();break;case 'export-bank':exportJSON({version:2,questions:bank},'labwise-question-bank.json');break;
 case 'confirm-import':{const result=await storeCustomBank(pendingImport);if(!result.ok){toast('Could not store this bank: '+result.error.message);break;}bank=pendingImport;byId=new Map(bank.map(q=>[q.id,q]));bankCustom=true;state.game=validateGame(state.game,bank);clearVoice();pendingImport=null;ui.bookId='';practice=null;cards=null;storeSession('practice');storeSession('cards');saveUI();closeModal();render();toast(`Imported ${bank.length.toLocaleString()} questions. Matching-ID progress is preserved.`);break;}
 case 'bundled':{const r=await deleteCustomBank();if(!r.ok){toast('Could not change bank preference: '+r.error.message);break;}bank=bundledBank;byId=new Map(bank.map(q=>[q.id,q]));bankCustom=false;state.game=validateGame(state.game,bank);clearVoice();ui.bookId='';practice=null;cards=null;storeSession('practice');storeSession('cards');saveUI();render();toast('Bundled source collections selected.');break;}
 case 'search-book':bookQuery=$('#book-search').value.trim();bookTopic=$('#book-topic').value;pageSearchLimit=12;$('#book-results').innerHTML=bookResults();break;
 case 'more-pages':pageSearchLimit+=12;$('#book-results').innerHTML=bookResults();break;case 'open-reader':openDocument(ui.readerDoc,state.reading[ui.readerDoc]||1,true);break;case 'cache-pdf':await cachePDF(b);break;
 case 'updates':if(window.LabwiseAndroid?.openUpdates)window.LabwiseAndroid.openUpdates();else window.open(UPDATE_URL,'_blank','noopener');break;
 }
});
document.addEventListener('change',e=>{
 const id=e.target.id;if(id==='game-clock-option'){flushGameClock();ui.playClock=e.target.checked;saveUI();render();return;}if(id==='voice-language'){ui.voiceLanguage=e.target.value;saveUI();return;}if(id.startsWith('setup-')){if(id==='setup-book'){$('#setup-topic').innerHTML='<option value="">All subjects</option>'+topicNames(e.target.value).map(t=>`<option>${esc(t)}</option>`).join('');}setupCount();return;}
 for(const k of ['practice','cards'])for(const field of ['topic','mode'])if(id===`${k}-${field}`){ui[k][field]=e.target.value;searchLimit=40;saveUI();render();}
 if(id==='reader-document'){ui.readerDoc=e.target.value;readerOpen=false;saveUI();render();}
 if(id==='goal'){state.goal=Number(e.target.value);save();render();}
 if(id==='font-size'){state.prefs.fontScale=Number(e.target.value);save();applyTheme();}
 if(id==='default-size'){state.prefs.sessionSize=Number(e.target.value);save();}
});
document.addEventListener('input',e=>{for(const k of ['practice','cards'])if(e.target.id===`${k}-query`){const pos=e.target.selectionStart;ui[k].query=e.target.value;searchLimit=40;saveUI();render();const input=$(`#${k}-query`);input.focus();try{input.setSelectionRange(pos,pos);}catch{}}});
document.addEventListener('submit',e=>{if(e.target.id==='page-form'){e.preventDefault();openDocument($('#reader-document').value,Number($('#page-number').value),true);}});
document.addEventListener('keydown',e=>{if(e.target.id==='book-search'&&e.key==='Enter'){e.preventDefault();$('[data-action="search-book"]').click();}const tab=e.target.closest('[role="tab"]');if(tab&&['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const tabs=[...tab.parentElement.querySelectorAll('[role="tab"]')],index=tabs.indexOf(tab),next=tabs[(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];next.click();next.focus();}});
$('#bank-input').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>25*1024*1024)throw Error('Question-bank files must be under 25 MB.');pendingImport=validateBank(JSON.parse(await f.text()));modal('Use this collection?',`<p><strong>${pendingImport.length.toLocaleString()} questions</strong> from ${new Set(pendingImport.map(q=>q.topic)).size} subjects. This changes your active bank; progress for matching IDs remains. Your bundled books can always be selected again.</p><p>Export your current custom bank first if you need its contents later.</p>`,btn('Cancel','close-dialog')+btn('Use this bank','confirm-import',true));}catch(error){toast(error.message);}finally{e.target.value='';}});
$('#progress-input').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>25*1024*1024)throw Error('Progress backups must be under 25 MB.');pendingRestore=validateBackup(JSON.parse(await f.text()));modal('Restore this progress?',`<p>This backup contains <strong>${Object.keys(pendingRestore.records).length.toLocaleString()} reviewed question records</strong>, ${pendingRestore.saved.length} saved questions and ${pendingRestore.log.length.toLocaleString()} study interactions, plus ${gameSummary(pendingRestore.game||blankGame()).xp.toLocaleString()} game XP.</p><p>It replaces the progress currently on this device. A previous copy is kept and Undo will be available.</p>`,btn('Cancel','close-dialog')+btn('Restore progress','confirm-restore',true));}catch(error){toast(error.message);}finally{e.target.value='';}});
window.addEventListener('popstate',e=>{flushGameClock();clearVoice();view=e.state?.view||location.hash.slice(1)||'home';practiceOpen=!!e.state?.session;render();});
window.labwiseBack=()=>{if($('#modal').open){closeModal();return true;}if(view==='play'&&!ui.playLobby&&state.game?.active){flushGameClock();clearVoice();ui.playLobby=true;saveUI();render();return true;}if(view==='practice'&&practiceOpen){navigate('practice');return true;}if(view!=='home'){navigate('home');return true;}return false;};
// Consume only a newly viewed native page, so a restored backup is not overwritten by stale reader state.
window.labwiseNativeReading=()=>{if(!loadReady||!window.LabwiseAndroid?.takeReadingPosition)return;try{const position=JSON.parse(window.LabwiseAndroid.takeReadingPosition());if(!position||!sourceDocument(catalog,position.documentId)||!Number.isInteger(position.page))return;state.reading[position.documentId]=readingPage(catalog,position.documentId,position.page);save();if(view==='library')render();}catch{}};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false;});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true;}};
document.querySelectorAll('.brand,.mobile-brand').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();navigate('home');}));
async function init(){try{
 const names=['catalog','study-bank','study-pages','teaching','teaching-coverage','glossary'];const [meta,raw,pageData,teaching,stats,vocab]=await Promise.all(names.map(async n=>{const r=await fetch(`./data/${n}.json`);if(!r.ok)throw Error('A source file could not load.');return r.json();}));catalog=meta;pages=pageData;coverage=stats;glossary=vocab;
 bundledBank=validateBank(raw.map(q=>({...q,...(teaching[q.id]?{teaching:teaching[q.id],simple:teaching[q.id].explanation,memory:teaching[q.id].memory}:{})})));const custom=await loadCustomBank();if(!custom.ok)storageWarning='Question-bank storage could not be read fully. Existing progress is kept; export a backup if needed.';try{bank=custom.value?validateBank(custom.value):bundledBank;bankCustom=!!custom.value;}catch{bank=bundledBank;toast('The saved custom bank could not be read. Bundled books are selected.');}
 state.game=validateGame(state.game,bank);byId=new Map(bank.map(q=>[q.id,q]));practice=validSession(readJSON('labwise-session',null).value,bank);cards=validSession(readJSON('labwise-cards-session',null).value,bank);if(!sourceDocument(catalog,ui.readerDoc))ui.readerDoc='textbook';if(ui.bookId&&!catalog.books.some(b=>b.id===ui.bookId))ui.bookId='';
 loadReady=true;window.labwiseNativeReading();setIcons();applyTheme();$('#date').textContent=new Date().toLocaleDateString(undefined,{timeZone:'Africa/Lagos',month:'short',day:'numeric'});view=['home','play','practice','cards','library','saved','progress'].includes(location.hash.slice(1))?location.hash.slice(1):'home';history.replaceState({view,session:false},'',`#${view}`);render();
 if(!window.LabwiseAndroid&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline app caching is not available in this browser.'));
 }catch(error){$('#content').innerHTML=title('LET’S RECONNECT','Your study space could not load.','Your saved progress is still on this device. Check the connection and reload.');toast(error.message);}}
init();
